-- 成果结构和周期边界属于持久化不变量，不能只依赖 API 表单校验。
DROP TRIGGER "achievement_validate_insert";
DROP TRIGGER "achievement_validate_update";

CREATE TRIGGER "achievement_validate_insert" BEFORE INSERT ON "achievement" BEGIN SELECT CASE WHEN NEW."source_type" NOT IN ('collected','manual') OR NEW."selection_status" NOT IN ('candidate','selected','excluded','needs_evidence') OR NEW."evidence_status" NOT IN ('complete','partial','needs_evidence') OR NEW."period_start" > NEW."period_end" OR NEW."period_start" < (SELECT "period_start" FROM "quarterly_review" WHERE "id" = NEW."review_id") OR NEW."period_end" > (SELECT "period_end" FROM "quarterly_review" WHERE "id" = NEW."review_id") OR length(trim(NEW."title")) < 1 OR length(trim(NEW."situation")) < 1 OR length(trim(NEW."action")) < 1 OR length(trim(NEW."result")) < 1 OR length(trim(NEW."impact")) < 1 OR length(trim(NEW."contribution_boundary")) < 1 OR NEW."version" < 1 OR (NEW."selection_status" = 'excluded' AND length(trim(COALESCE(NEW."exclusion_reason", ''))) < 1) THEN RAISE(ABORT, 'achievement values are invalid') END; END;
CREATE TRIGGER "achievement_validate_update" BEFORE UPDATE ON "achievement" BEGIN SELECT CASE WHEN NEW."review_id" <> OLD."review_id" OR COALESCE(NEW."collection_snapshot_id", '') <> COALESCE(OLD."collection_snapshot_id", '') OR NEW."source_type" <> OLD."source_type" OR NEW."source_key" <> OLD."source_key" OR NEW."selection_status" NOT IN ('candidate','selected','excluded','needs_evidence') OR NEW."evidence_status" NOT IN ('complete','partial','needs_evidence') OR NEW."period_start" > NEW."period_end" OR NEW."period_start" < (SELECT "period_start" FROM "quarterly_review" WHERE "id" = NEW."review_id") OR NEW."period_end" > (SELECT "period_end" FROM "quarterly_review" WHERE "id" = NEW."review_id") OR length(trim(NEW."title")) < 1 OR length(trim(NEW."situation")) < 1 OR length(trim(NEW."action")) < 1 OR length(trim(NEW."result")) < 1 OR length(trim(NEW."impact")) < 1 OR length(trim(NEW."contribution_boundary")) < 1 OR NEW."version" <= OLD."version" OR (NEW."selection_status" = 'excluded' AND length(trim(COALESCE(NEW."exclusion_reason", ''))) < 1) THEN RAISE(ABORT, 'achievement transition is invalid') END; END;

CREATE TRIGGER "achievement_evidence_validate_insert" BEFORE INSERT ON "achievement_evidence" BEGIN SELECT CASE WHEN length(trim(NEW."source_type")) < 1 OR length(trim(NEW."source_id")) < 1 OR length(trim(NEW."title")) < 1 OR NEW."availability_state" NOT IN ('available','stale','unavailable','unknown') OR length(trim(NEW."contribution_angle")) < 1 THEN RAISE(ABORT, 'achievement_evidence values are invalid') END; END;
